                  <Text dimColor>{'  '}no command running, the model is thinking</Text>
                ) : null}
                {run.procs.filter(x => !x.isHelper).map((p, i) => (
                  <Box key={`p${i}`} gap={1}>
                    <Text color="green">{'  ▸'}</Text>
